python3 << 'PYEOF'
config = open('/etc/nginx/sites-enabled/globalelection').read()
uploads_loc = """
    location /uploads/ {
        alias /var/www/globalelectionnetwork/public/uploads/;
        expires 30d;
        add_header Cache-Control \"public\";
        add_header Access-Control-Allow-Origin \"*\";
    }

"""
marker = 'server_name globalelectionnetwork.com www.globalelectionnetwork.com; # managed by Certbot'
if uploads_loc.strip() not in config:
    config = config.replace(marker, marker + '\n' + uploads_loc, 1)
    open('/etc/nginx/sites-enabled/globalelection', 'w').write(config)
    print('Nginx config updated')
else:
    print('Already has uploads block')
PYEOF
